def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    books = image_patch.find("book")
    tables = image_patch.find("table")

    if not books or not tables:
        return image_patch

    books_on_tables = []
    for book in books:
        for table in tables:
            if book.overlaps_with(table.left, table.lower, table.right, table.upper):
                books_on_tables.append(book)

    if not books_on_tables:
        return image_patch

    books_on_tables.sort(key=lambda b: abs(b.horizontal_center - tables[0].horizontal_center))
    return books_on_tables[-1]

